require_once 'config.php';require_once 'includes/functions.php';wajibLogin();$id=(int)($_GET['id']??0);$s=$pdo->prepare('SELECT t.*,p.nama_pelanggan,p.kota FROM tbl_transaksi t JOIN tbl_pelanggan p ON p.id_pelanggan=t.id_pelanggan WHERE t.id_transaksi=?');$s->execute([$id]);$t=$s->fetch();if(!$t){http_response_code(404);exit('Transaksi tidak ditemukan.');}$s=$pdo->prepare('SELECT * FROM tokoku_detail_transaksi WHERE id_transaksi=?');$s->execute([$id]);$items=$s->fetchAll();$pageTitle='Struk Penjualan';?>
